import{_ as s,o as n,c as e,a2 as t}from"./chunks/framework.C4u7U0Dw.js";const g=JSON.parse('{"title":"第 10 章 写代码：脚本、修改与调试","description":"","frontmatter":{},"headers":[],"relativePath":"bluebook/第二篇 案例篇：从一项任务到一支 AI 团队/第 10 章 写代码：脚本、修改与调试.md","filePath":"bluebook/第二篇 案例篇：从一项任务到一支 AI 团队/第 10 章 写代码：脚本、修改与调试.md"}'),l={name:"bluebook/第二篇 案例篇：从一项任务到一支 AI 团队/第 10 章 写代码：脚本、修改与调试.md"};function i(o,a,p,r,d,c){return n(),e("div",null,[...a[0]||(a[0]=[t(`<h1 id="第-10-章-写代码-脚本、修改与调试" tabindex="-1">第 10 章 写代码：脚本、修改与调试 <a class="header-anchor" href="#第-10-章-写代码-脚本、修改与调试" aria-label="Permalink to &quot;第 10 章 写代码：脚本、修改与调试&quot;">​</a></h1><h2 id="_10-1-场景" tabindex="-1">10.1 场景 <a class="header-anchor" href="#_10-1-场景" aria-label="Permalink to &quot;10.1 场景&quot;">​</a></h2><p>代码类任务是我的核心场景之一。包括：</p><ul><li><strong>写脚本</strong>：自动化、批处理、数据处理；</li><li><strong>改代码</strong>：修 bug、加功能、重构；</li><li><strong>调试</strong>：定位报错、分析日志、验证修复。</li></ul><h2 id="_10-2-写代码的铁律" tabindex="-1">10.2 写代码的铁律 <a class="header-anchor" href="#_10-2-写代码的铁律" aria-label="Permalink to &quot;10.2 写代码的铁律&quot;">​</a></h2><ol><li><strong>先读后改</strong>：改任何代码前，先 Read 完整上下文；</li><li><strong>最小改动</strong>：能改一行不重写十行，diff 越小越安全；</li><li><strong>验证优先</strong>：写完必须跑，不能&quot;我觉得没问题&quot;；</li><li><strong>可回退</strong>：让你能看到改动内容，随时可以撤销。</li></ol><h2 id="_10-3-案例-写一个批处理脚本" tabindex="-1">10.3 案例：写一个批处理脚本 <a class="header-anchor" href="#_10-3-案例-写一个批处理脚本" aria-label="Permalink to &quot;10.3 案例：写一个批处理脚本&quot;">​</a></h2><p><strong>指令：</strong></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>写一个 PowerShell 脚本，把 downloads/ 下所有 .jpg 按拍摄日期</span></span>
<span class="line"><span>重命名（IMG_YYYYMMDD_序号.jpg），并输出处理日志。</span></span>
<span class="line"><span>要求：先试运行（-WhatIf），确认无误再真正执行。</span></span></code></pre></div><p><strong>我的做法：</strong></p><ol><li>先 Glob 看看目录里有多少文件、命名规律；</li><li>写脚本，加 <code>-WhatIf</code> 干跑模式；</li><li>先试运行，把&quot;将要执行的动作&quot;列给你看；</li><li>你确认后，正式执行并输出日志。</li></ol><h2 id="_10-4-案例-修一个-bug" tabindex="-1">10.4 案例：修一个 bug <a class="header-anchor" href="#_10-4-案例-修一个-bug" aria-label="Permalink to &quot;10.4 案例：修一个 bug&quot;">​</a></h2><p><strong>指令：</strong></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>src/app.py 运行报 KeyError: &#39;user_id&#39;，帮我定位并修复。</span></span>
<span class="line"><span>报错堆栈：</span></span>
<span class="line"><span>（贴堆栈）</span></span></code></pre></div><p><strong>我的做法：</strong></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Read app.py（看现场）</span></span>
<span class="line"><span>→ Grep &#39;user_id&#39;（查所有相关位置）</span></span>
<span class="line"><span>→ 判断：是字段名拼写？还是数据源缺字段？</span></span>
<span class="line"><span>→ Edit 最小修复</span></span>
<span class="line"><span>→ 跑测试/复现命令验证</span></span>
<span class="line"><span>→ 让你 review diff</span></span></code></pre></div><h2 id="_10-5-调试方法论" tabindex="-1">10.5 调试方法论 <a class="header-anchor" href="#_10-5-调试方法论" aria-label="Permalink to &quot;10.5 调试方法论&quot;">​</a></h2><p>调试不是瞎试，而是<strong>二分定位</strong>：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>复现 → 缩小范围（注释掉一半代码）→ 定位到函数 → 定位到行 → 确认根因 → 修复 → 验证</span></span></code></pre></div><p>我可以帮你做大部分定位工作，但<strong>根因判断需要你提供业务背景</strong>——这正是人机协作最有价值的地方。</p><h2 id="_10-6-代码任务的边界与安全" tabindex="-1">10.6 代码任务的边界与安全 <a class="header-anchor" href="#_10-6-代码任务的边界与安全" aria-label="Permalink to &quot;10.6 代码任务的边界与安全&quot;">​</a></h2><ul><li><strong>执行有副作用的命令</strong>（删除、覆盖、装依赖、推远程）先问你；</li><li><strong>敏感信息</strong>（密钥、密码）不要写进代码和记忆；</li><li><strong>生产环境操作</strong>：要求我先给出影响评估再执行。</li></ul><h2 id="_10-7-练习" tabindex="-1">10.7 练习 <a class="header-anchor" href="#_10-7-练习" aria-label="Permalink to &quot;10.7 练习&quot;">​</a></h2><ol><li>给我一个真实的批处理需求，要求先试运行再执行；</li><li>给我一个报错信息，让我走一遍&quot;定位 → 修复 → 验证&quot;；</li><li>把常用的调试指令存成记忆或 Skill。</li></ol><blockquote><p>小结：写代码，AI 赢在速度和广度；<strong>验证和放行，永远在你手里。</strong></p></blockquote>`,25)])])}const u=s(l,[["render",i]]);export{g as __pageData,u as default};
